<script setup lang="ts">
import type { Product,CartLine } from '@ellas/shared';
const route=useRoute();const selection=useSelection();
const {data:product,error}=await useFetch<Product>(`/api/catalog/products/${route.params.slug}`);
if(error.value || !product.value) throw createError({statusCode:404,statusMessage:'Prenda no encontrada'});
useSeo(`${product.value.name} · ${product.value.reference}`,product.value.description);
const variantConfig=ref<{clearAdded:()=>void}>();
function addConfigured(lines:CartLine[]){if(selection.add(lines)){validation.value='';variantConfig.value?.clearAdded();}else validation.value=selection.validation;}
const validation=ref('');
const jsonLd=computed(()=>({'@context':'https://schema.org','@type':'Product',name:product.value?.name,sku:product.value?.reference,description:product.value?.description,image:new URL(product.value?.image || '/',useRuntimeConfig().public.appUrl).href,brand:{'@type':'Brand',name:'JHK T-Shirt'},material:product.value?.composition}));
useHead({script:[{type:'application/ld+json',innerHTML:JSON.stringify(jsonLd.value).replace(/</g,'\\u003c')}]});
</script>
<template><div v-if="product" class="container product-page"><div class="breadcrumb"><NuxtLink to="/">Inicio</NuxtLink><span>/</span><NuxtLink to="/catalogo">Catálogo</NuxtLink><span>/</span><span>{{product.reference}}</span></div><div class="product-detail"><div class="product-gallery"><div class="product-main-photo"><img :src="product.image" :alt="product.name" :width="product.imageWidth" :height="product.imageHeight" fetchpriority="high" /><span class="photo-caption">JHK / {{product.collection}} / 2026</span></div><div class="product-promise"><AppIcon name="CheckCircle2" :size="18" /><span>Fotografía y especificaciones del catálogo JHK 2026.</span></div></div><div class="product-content"><div class="product-heading"><span class="eyebrow">{{product.collection}} <span class="separator">/</span> {{product.audience}}</span><span class="ref-label">REF. {{product.reference}}</span></div><h1>{{product.name}}</h1><p class="product-description">{{product.description}}</p><div class="product-price">Precio bajo presupuesto <span>Lo preparamos a la medida de tu equipo.</span></div><div class="product-specs"><span><b>Tejido</b>{{product.composition || 'Consultar ficha original'}}</span><span v-if="product.weight"><b>Gramaje</b>{{product.weight}} g/m² aprox.</span><span><b>Opciones</b>{{product.colors.length}} colores · {{product.sizes.length}} tallas</span></div><VariantConfigurator ref="variantConfig" :product="product" @add="addConfigured"/><p v-if="validation" class="field-error" role="alert">{{validation}}</p><NuxtLink to="/hacer-pedido" class="button outline full">Revisar mi pedido <AppIcon name="ArrowRight"/></NuxtLink></div></div><section class="technical-details"><div><span class="eyebrow">LA PRENDA, EN DETALLE</span><h2>Que todo <span class="serif-word">encaje.</span></h2><p v-for="note in product.compositionNotes" :key="note">{{note}}</p><p class="fine-print">Fuente: catálogo JHK 2026, páginas {{product.source.printedPages}}. Las medidas son aproximadas. Compara con una prenda que te siente bien.</p><a :href="product.source.supplierUrl" target="_blank" rel="noopener" class="text-link">Ficha del fabricante <AppIcon name="ExternalLink" :size="16" /></a></div><div><h3>Guía de medidas</h3><div v-if="product.measurements.length" class="table-scroll"><table class="measurements-table"><thead><tr><th>Talla</th><th v-for="key in Object.keys(product.measurements[0]?.values || {})" :key="key">{{key}}</th></tr></thead><tbody><tr v-for="row in product.measurements" :key="row.size"><th>{{row.size}}</th><td v-for="(value,key) in row.values" :key="key">{{value}}</td></tr></tbody></table></div><p v-else>Consulta las medidas en la ficha original de abajo o con nuestro equipo.</p></div></section><details class="source-details"><summary>Consultar ficha original del catálogo <AppIcon name="ChevronDown" /></summary><div class="source-images"><img v-for="src in product.sourceImages" :key="src" :src="src" alt="Ficha original JHK 2026 con tallas, colores y composición" width="1150" height="1559" loading="lazy" /></div></details><div class="product-bottom-cta"><AppIcon name="Shirt" :size="28" /><div><h3>¿Le ponemos vuestra firma?</h3><p>Podrás añadir tu logo y pedir personalización al enviar la selección.</p></div><NuxtLink to="/personalizacion" class="text-link">Ver opciones <AppIcon name="ArrowUpRight" /></NuxtLink></div></div></template>
